/** @defgroup STM3210C_EVAL_SD_Private_Variables STM3210C EVAL SD Private Variables
  * @{
  */       
__IO uint8_t SdStatus = SD_NOT_PRESENT;

/* flag_SDHC :
      0 :  Standard capacity
      1 : High capacity
*/
uint16_t flag_SDHC = 0; 

